onChange.script:
items = self.props.items
first = 0 
second = 0
third = 0 
last = 0
end = False
if items:
	for x in items:
		if end:
			break
		if currentValue.value == x['target']:
			second = 0
			third = 0
			last = 0
			end = True

		first += 1

		second = 0
		if x['items']:

			for z in x['items']:
				if end:
					break

				if currentValue.value == z['target']:
					third = 0
					last = 0		
					end = True

				second += 1
				third = 0
				if z['items']:

					for i in z['items']:
						if end:
							break
						if currentValue.value == i['target']:
							last = 0
							end = True

						third += 1

						last = 0
						if i['items']:

							for w in i['items']:
								if end:
									break
								if currentValue.value == w['target']:
									end = True


								last += 1

	if end == False:
		first = 0 
		second = 0
		third = 0 
		last = 0
		end = False
		if items:
			for x in items:
				if end:
					break
				if currentValue.value.split('/')[1] == x['target'].split('/')[1]:
					second = 0
					third = 0
					last = 0
					end = True

				first += 1

				second = 0



	if self.custom.old is not None:
		firstOld, secondOld, thirdOld, lastOld = self.custom.old

		if lastOld != 0:
			self.props.items[firstOld-1].items[secondOld-1].items[thirdOld-1].items[lastOld-1].style.classes = ''
		if thirdOld != 0:
			self.props.items[firstOld-1].items[secondOld-1].items[thirdOld-1].style.classes = ''
		if secondOld != 0:
			self.props.items[firstOld-1].items[secondOld-1].style.classes = ''
		if firstOld != 0:
			self.props.items[firstOld-1].style.classes = ''			

	if end == True:
		if last != 0:
			self.props.items[first-1].items[second-1].items[third-1].items[last-1].style.classes = 'horizontal-menu-border-selected'
		if third != 0:
			self.props.items[first-1].items[second-1].items[third-1].style.classes = 'horizontal-menu-border-selected'
		if second != 0:
			self.props.items[first-1].items[second-1].style.classes = 'horizontal-menu-border-selected'
		if first != 0:
			self.props.items[first-1].style.classes = 'horizontal-menu-border-selected'	

		self.custom.old = first, second, third, last

transforms.code:
try:
	if "it/security" not in self.page.props.path:
		path = "Security/getPageRights"		
		parameters = {"userSource":self.session.props.auth.idp,"username":self.session.props.auth.user.userName,"url":self.page.props.path}
		data = system.db.runNamedQuery(path,parameters=parameters)
		if len(data):
			securityData = data[0]
			self.session.custom.security = securityData
			if securityData['ReadAllowed'] == False:
				system.perspective.navigate("/")
		else:
			self.session.custom.security = {
			    "navigation_path": "/",
			    "CreateAllowed": False,
			    "ReadAllowed": False,
			    "UpdateAllowed": False,
			    "DeleteAllowed": False
			  }
			system.perspective.navigate("/")
		return True
	else:
		return True

except:
	return False
